# AST node

class Node:

  def __init__(self, key, size, synthesizable=False):
    self.key = key
    self.cost = 1
    self.size = size
    self.children = []
    self.variables = set()
    self.constants = set()
    self.distribution = {}
    self.synthesizable = synthesizable

  def is_synthesizable(self):
    return self.synthesizable

  def set_synthesizable(self, synthesizable):
    self.synthesizable = synthesizable

  def __repr__(self):
    tag = '[$]' if self.synthesizable else ''
    if self.children:
      return f'{tag}{self.key}({", ".join(str(child) for child in self.children)})'
    else:
      return f'{tag}{self.key}'

  def to_rpn(self):
    operations = {
      'AddW': '+',
      'SubW': '-',
      'MulW': '*',
      'AndW': '&',
      'XorW': '^',
      'OrW': '|',
      'NegW': ':',
      'NotW': '~',
      'ShlW': '<',
      'ShrW': '>'
    }
    if len(self.children) == 2:
      operation = operations[self.key]
      return f'{self.children[0].to_rpn()}{self.children[1].to_rpn()}{operation}'
    elif len(self.children) == 1:
      operation = operations[self.key]
      return f'{self.children[0].to_rpn()}{operation}'
    elif self.key.startswith('WV_'):
      value = self.key.replace('WV_', '')
      return f'{value}'
    elif self.key.startswith('K_'):
      number = int(self.key.replace('K_', ''), 16)
      if ('-' in self.key) and (number < 0):
        number = -number
      return f'k{number:016X}'
    else:
      return f'{self.key}'

  def to_exp(self):
    operations = {
      'AddW': '+',
      'SubW': '-',
      'MulW': '*',
      'AndW': '&',
      'XorW': '^',
      'OrW': '|',
      'NegW': '-',
      'NotW': '~',
      'ShlW': '<<',
      'ShrW': '>>'
    }
    if len(self.children) == 2:
      operation = operations[self.key]
      return f'({self.children[0].to_exp()}{operation}{self.children[1].to_exp()})'
    elif len(self.children) == 1:
      operation = operations[self.key]
      return f'({operation}{self.children[0].to_exp()})'
    elif self.key.startswith('WV_'):
      value = self.key.replace('WV_', '')
      return f'{value}'
    elif self.key.startswith('K_'):
      number = int(self.key.replace('K_', ''), 16)
      return f'{hex(number)}'
    else:
      return f'{str(self)}'

  def get_constants(self):
    return self.constants

  def get_variables(self):
    return self.variables

  def get_node_cost(self):
    return self.cost

  def get_node_count(self, key):
    if key in self.distribution:
      return self.distribution[key]
    return 0

  def update_internal_state(self):
    # Update the variables and distribution
    for child in self.children:
      self.cost += child.cost
      if child:
        self.variables |= child.variables
        self.constants |= child.constants
        for child_key, child_count in child.distribution.items():
          if child_key not in self.distribution:
            self.distribution[child_key] = 0
          self.distribution[child_key] += child_count
    # Count the current node too
    if self.key not in self.distribution:
      self.distribution[self.key] = 0
    self.distribution[self.key] += 1

class WordNode(Node):

  def __init__(self, key, synthesizable=False):
    super().__init__(key, BITS, synthesizable)

  def __pow__(self, other):
    if not isinstance(other, int):
      print(f'Exponentiation without a constant: {other}')
      exit(-1)
    if other == 0:
      return WordConstant(1)
    node = self
    for i in range(other - 1):
      node = MulW(self, node)
    return node

  def __add__(self, other):
    if isinstance(other, int):
      other &= (2**BITS-1)
      other = WordConstant(other)
    return AddW(self, other)

  def __radd__(self, other):
    return self.__add__(other)

  def __sub__(self, other):
    if isinstance(other, int):
      other &= (2**BITS-1)
      other = WordConstant(other)
    return SubW(self, other)

  def __rsub__(self, other):
    if isinstance(other, int):
      other &= (2**BITS-1)
      other = WordConstant(other)
    return SubW(other, self)

  def __mul__(self, other):
    if isinstance(other, int):
      other &= (2**BITS-1)
      other = WordConstant(other)
    return MulW(self, other)

  def __rmul__(self, other):
    return self.__mul__(other)

  def __and__(self, other):
    if isinstance(other, int):
      other &= (2**BITS-1)
      other = WordConstant(other)
    return AndW(self, other)

  def __rand__(self, other):
    return self.__and__(other)

  def __or__(self, other):
    if isinstance(other, int):
      other &= (2**BITS-1)
      other = WordConstant(other)
    return OrW(self, other)

  def __ror__(self, other):
    return self.__or__(other)

  def __xor__(self, other):
    if isinstance(other, int):
      other &= (2**BITS-1)
      other = WordConstant(other)
    return XorW(self, other)

  def __rxor__(self, other):
    return self.__xor__(other)

  def __invert__(self):
    return NotW(self)

  def __neg__(self):
    return NegW(self)

  def __lshift__(self, other):
    if isinstance(other, int):
      other &= (2**BITS-1)
      other = WordConstant(other)
    return ShlW(self, other)

  def __rlshift__(self, other):
    if isinstance(other, int):
      other &= (2**BITS-1)
      other = WordConstant(other)
    return other.__lshift__(self)

  def __rshift__(self, other):
    if isinstance(other, int):
      other &= (2**BITS-1)
      other = WordConstant(other)
    return ShrW(self, other)

  def __rrshift__(self, other):
    if isinstance(other, int):
      other &= (2**BITS-1)
      other = WordConstant(other)
    return other.__rshift__(self)

class WordPlaceholder(WordNode):

  def __init__(self, name):
    super().__init__(name)

  def __repr__(self):
    return self.key

class WordVariable(WordNode):

  def __init__(self, name):
    super().__init__('WV_' + name)
    self.variables.add(name)

  def __repr__(self):
    return self.key.replace('WV_', '')

  def evaluate(self, values, mask):
    name = self.key.replace('WV_', '')
    return values[name] & mask

  def as_exp(self, variables, cache):
    name = self.key.replace('WV_', '')
    if name in cache:
      variable = cache[name]
    else:
      variable = variables.pop()
      cache[name] = variable
    return f"{variable}"

  def set_name(self, name):
    self.key = 'WV_' + name

  def get_name(self):
    return self.key.replace('WV_', '')

class WordConstant(WordNode):

  def __init__(self, key):
    if isinstance(key, int):
      super().__init__(f'K_{key:x}')
    elif isinstance(key, str):
      super().__init__(key)
    else:
      print(f"Unexpected constant value type: {type(key)}, value: {key}")
      exit(1)
    self.constants.add(self.key)

  def __repr__(self):
    number = self.key.replace('K_', '')
    return f'{hex(int(number, 16))}'

  def evaluate(self, values, mask):
    return int(self.key.replace('K_', ''), 16)

  def as_exp(self, variables, cache):
    return f"{int(self.key.replace('K_', ''), 16)}"

  def as_int(self):
    return int(self.key.replace('K_', ''), 16)

class WordUnaryOperation(WordNode):

  def __init__(self, key, op, synthesizable=False):
    super().__init__(key, synthesizable)
    # Update the children
    self.children.append(op)
    # Update the variables and distribution
    self.update_internal_state()

class WordBinaryOperation(WordNode):

  def __init__(self, key, op0, op1, synthesizable=False):
    super().__init__(key, synthesizable)
    # Update the children
    self.children.append(op0)
    self.children.append(op1)
    # Update the variables and distribution
    self.update_internal_state()

class NotW(WordUnaryOperation):

  def __init__(self, op, synthesizable=False):
    super().__init__('NotW', op, synthesizable)

  def evaluate(self, values, mask):
    c0 = self.children[0].evaluate(values, mask)
    result = (~c0) & mask
    return result

  def as_exp(self, variables, cache):
    return f"(~{self.children[0].as_exp(variables, cache)})"

class NegW(WordUnaryOperation):

  def __init__(self, op, synthesizable=False):
    super().__init__('NegW', op, synthesizable)

  def evaluate(self, values, mask):
    return (-self.children[0].evaluate(values, mask)) & mask

  def as_exp(self, variables, cache):
    return f"(-{self.children[0].as_exp(variables, cache)})"

class AndW(WordBinaryOperation):

  def __init__(self, op0, op1, synthesizable=False):
    super().__init__('AndW', op0, op1, synthesizable)

  def evaluate(self, values, mask):
    return (self.children[0].evaluate(values, mask) & self.children[1].evaluate(values, mask)) & mask

  def as_exp(self, variables, cache):
    return f"({self.children[0].as_exp(variables, cache)} & {self.children[1].as_exp(variables, cache)})"

class MulW(WordBinaryOperation):

  def __init__(self, op0, op1, synthesizable=False):
    super().__init__('MulW', op0, op1, synthesizable)

  def evaluate(self, values, mask):
    return (self.children[0].evaluate(values, mask) * self.children[1].evaluate(values, mask)) & mask

  def as_exp(self, variables, cache):
    return f"({self.children[0].as_exp(variables, cache)} * {self.children[1].as_exp(variables, cache)})"

class AddW(WordBinaryOperation):

  def __init__(self, op0, op1, synthesizable=False):
    super().__init__('AddW', op0, op1, synthesizable)

  def evaluate(self, values, mask):
    return (self.children[0].evaluate(values, mask) + self.children[1].evaluate(values, mask)) & mask

  def as_exp(self, variables, cache):
    return f"({self.children[0].as_exp(variables, cache)} + {self.children[1].as_exp(variables, cache)})"

class SubW(WordBinaryOperation):

  def __init__(self, op0, op1, synthesizable=False):
    super().__init__('SubW', op0, op1, synthesizable)

  def evaluate(self, values, mask):
    c0 = self.children[0].evaluate(values, mask)
    c1 = self.children[1].evaluate(values, mask)
    result = (c0 - c1) & mask
    return result

  def as_exp(self, variables, cache):
    return f"({self.children[0].as_exp(variables, cache)} - {self.children[1].as_exp(variables, cache)})"

class ShlW(WordBinaryOperation):

  def __init__(self, op0, op1, synthesizable=False):
    super().__init__('ShlW', op0, op1, synthesizable)

  def evaluate(self, values, mask):
    c0 = self.children[0].evaluate(values, mask)
    c1 = self.children[1].evaluate(values, mask)
    result = (c0 << c1) & mask
    return result

  def as_exp(self, variables, cache):
    return f"({self.children[0].as_exp(variables, cache)} << {self.children[1].as_exp(variables, cache)})"

class ShrW(WordBinaryOperation):

  def __init__(self, op0, op1, synthesizable=False):
    super().__init__('ShrW', op0, op1, synthesizable)

  def evaluate(self, values, mask):
    c0 = self.children[0].evaluate(values, mask)
    c1 = self.children[1].evaluate(values, mask)
    result = LShr(c0, c1, mask)
    return result

  def as_exp(self, variables, cache):
    return f"({self.children[0].as_exp(variables, cache)} >> {self.children[1].as_exp(variables, cache)})"

class XorW(WordBinaryOperation):

  def __init__(self, op0, op1, synthesizable=False):
    super().__init__('XorW', op0, op1, synthesizable)

  def evaluate(self, values, mask):
    return (self.children[0].evaluate(values, mask) ^ self.children[1].evaluate(values, mask)) & mask

  def as_exp(self, variables, cache):
    return f"({self.children[0].as_exp(variables, cache)} ^ {self.children[1].as_exp(variables, cache)})"

class OrW(WordBinaryOperation):

  def __init__(self, op0, op1, synthesizable=False):
    super().__init__('OrW', op0, op1, synthesizable)

  def evaluate(self, values, mask):
    return (self.children[0].evaluate(values, mask) | self.children[1].evaluate(values, mask)) & mask

  def as_exp(self, variables, cache):
    return f"({self.children[0].as_exp(variables, cache)} | {self.children[1].as_exp(variables, cache)})"

