class ENode:

  index = 0

  def __init__(self, key, children):
    self.id = ENode.index
    self.key = key
    self.children = children
    ENode.index += 1

  def __repr__(self):
    return f'(id = {self.id}, key = {self.key}, children = {self.children})'

  def __hash__(self):
    return hash((self.key, self.children))

  def __eq__(self, other):
    return ((self.key, self.children) == (other.key, other.children))

  def __lt__(self, other):
    return ((self.key, self.children) < (other.key, other.children))

  def is_leaf(self):
    return self.key in ['Zero', 'One', 'Any'] or self.key.startswith('K') or self.key.startswith('R')

