class EClass:

  def __init__(self, id, size, nodes):
    # print(f'new_id: {id}, nodes: {nodes}')
    self.id = id
    self.size = size
    self.nodes = nodes
    self.parents = [] # parents: Vec<(L, Id)>

  def len(self):
    return len(self.nodes)

  def leaves(self):
    return [ node for node in self.nodes if node.is_leaf() ]

  def assert_unique_leaves(self):
    if not (len(self.leaves()) <= 1):
      print(f"id: {self.id} => {self.leaves()}")
    assert len(self.leaves()) <= 1

  def __repr__(self):
    return f'e{self.id}'

# ================================================================================================================

class UnionFind:

  def __init__(self):
    self.parents = []

  def make_set(self):
    parent = len(self.parents)
    self.parents.append(parent)
    return parent

  def size(self):
    return len(self.parents)

  def parent(self, id):
    return self.parents[id]

  def find(self, current):
    while current != self.parent(current):
      current = self.parent(current)
    return current

  def find_mut(self, current):
    while current != self.parent(current):
      grandparent = self.parent(self.parent(current))
      self.parents[current] = grandparent
      current = grandparent
    return current

  def union(self, root1, root2):
    self.parents[root2] = root1
    return root1

  def __repr__(self):
    return f'{self.parents}'

# ================================================================================================================

class MatchState:

  def __init__(self, environment, eclasses, enodes):
    self.environment = environment
    self.eclasses = eclasses
    self.enodes = enodes
    self.string = None

  def has_next(self):
    return len(self.eclasses) != 0 and len(self.enodes) != 0

  def next(self):
    if self.has_next():
      return self.eclasses.pop(), self.enodes.pop()
    raise Exception('next: nothing more to match!')

  def update(self, eclasses, enodes):
    self.eclasses += eclasses
    self.enodes += enodes

  def fork(self):
    return MatchState(self.environment.copy(), self.eclasses.copy(), self.enodes.copy())

  def __repr__(self):
    if self.string:
      return self.string
    self.string = f'(environment = {self.environment}, eclasses = {self.eclasses}, enodes = {self.enodes})'
    return self.string

