class EGraph:

  def __init__(self):
    self.unionfind = UnionFind()  # unionfind: UnionFind
    self.memo = {}                # memo: HashMap<L, Id>
    self.pending = []             # Vec<(L, Id)>
    self.classes = {}             # classes: HashMap<Id, EClass<L, N::Data>>
    self.clean = False

  def size(self):
    return self.unionfind.size()

  def eclasses(self):
    return self.classes.values()

  def find(self, id):
    return self.unionfind.find(id)

  def find_mut(self, id):
    return self.unionfind.find_mut(id)

  def canonicalize(self, enode):
    enode.children = tuple(self.find(id) for id in enode.children)

  def canonicalize_mut(self, enode):
    enode.children = tuple(self.find_mut(id) for id in enode.children)

  def __getitem__(self, id):
    id = self.find(id)
    return self.classes[id]

  def __setitem__(self, id, eclass):
    id = self.find(id)
    self.classes[id] = eclass

  def add_expression(self, expression):
    id = self.add_expression_internal(expression)
    return self.find(id)

  def add_expression_internal(self, expression):
    # Use a worklist to avoid recursion
    worklist = [ (False, expression) ]
    cache = {}
    while worklist:
      # Fetch the node
      done, node = worklist.pop()
      # Check if already converted
      if node in cache:
        continue
      # Populate it or queue its children
      if done:
        enode = ENode(node.key, tuple(cache[child] for child in node.children))
        cache[node] = self.add_internal(enode, node.size)
      else:
        worklist.append((True, node))
        for child in node.children:
          worklist.append((False, child))
    # Return the converted expression
    return cache[expression]

  def add_instantiation(self, replacement, environment):
    id = self.add_instantiation_internal(replacement, environment)
    return self.find(id)

  def add_instantiation_internal(self, replacement, environment):
    # Use a worklist to avoid recursion
    worklist = [ (False, replacement) ]
    cache = {}
    while worklist:
      # Fetch the node
      done, node = worklist.pop()
      # Check if it has been already converted
      if node in cache:
        continue
      # Check if it's a variable
      if isinstance(node, WordPlaceholder):
        cache[node] = environment[node.key]
        continue
      # Populate it or queue its children
      if done:
        enode = ENode(node.key, tuple(cache[child] for child in node.children))
        cache[node] = self.add_internal(enode, node.size)
      else:
        worklist.append((True, node))
        for child in node.children:
          worklist.append((False, child))
    # Return the eclass
    return cache[replacement]

  def lookup_internal(self, enode):
    self.canonicalize(enode)
    return self.memo.get(enode, None)

  def add(self, enode, size):
    id = self.add_internal(enode, size)
    return self.find(id)

  def add_internal(self, enode, size):
    existing_id = self.lookup_internal(enode)
    if existing_id is not None:
      return existing_id
    else:
      id = self.make_new_eclass(enode, size)
      self.clean = False
      return id

  def make_new_eclass(self, enode, size):
    id = self.unionfind.make_set()
    eclass = EClass(id, size, [enode])
    for child in enode.children:
      self[child].parents.append((enode, id))
    self.pending.append((enode, id))
    self[id] = eclass
    assert enode not in self.memo
    self.memo[enode] = id
    return id

  def union(self, id1, id2):
    self.perform_union(id1, id2)

  def perform_union(self, id1, id2):
    self.clean = False
    id1 = self.find_mut(id1)
    id2 = self.find_mut(id2)
    if id1 == id2:
      return False
    class1_parents = len(self.classes[id1].parents)
    class2_parents = len(self.classes[id2].parents)
    if class1_parents < class2_parents:
      id1, id2 = id2, id1
    self.unionfind.union(id1, id2)
    assert id1 != id2
    class2 = self.classes.pop(id2)
    class1 = self.classes[id1]
    assert class1.id == id1
    self.pending += class2.parents.copy()
    class1.nodes += class2.nodes
    class1.parents += class2.parents
    return True

  def rebuild_classes(self):
    trimmed = 0
    for eclass in self.eclasses():
      old_len = eclass.len()
      for enode in eclass.nodes:
        self.canonicalize_mut(enode)
      eclass.nodes = list(set(eclass.nodes))
      # eclass.nodes.sort()
      eclass.nodes = sorted(eclass.nodes, key=lambda e: e.id)
      trimmed += (old_len - eclass.len())
    return trimmed

  def process_unions(self):
    n_unions = 0
    while self.pending:
      enode, eclass = self.pending.pop()
      self.canonicalize_mut(enode)
      memo_class = self.memo.get(enode, None)
      self.memo[enode] = eclass
      if memo_class:
        if self.perform_union(eclass, memo_class):
          n_unions += 1
    return n_unions

  def rebuild(self):
    n_unions = self.process_unions()
    self.rebuild_classes()
    self.check_memo()
    self.check_eclasses()
    self.clean = True
    return n_unions

  def ematch(self, pattern):
    # Match the pattern across all the eclasses
    matches = []
    for id in self.classes.keys():
      # Keep a backlog of forked states
      state = MatchState({}, [id], [pattern])
      worklist = [ state ]
      while worklist:
        # Fetch a forked state
        state = worklist.pop()
        # Visit a single path at a time and defer the forks
        while state:
          # Check if we completed the match
          if not state.has_next():
            matches.append((id, state.environment))
            state = None
          else:
            # Fetch the next eclass id, eclass and node to match
            n_id, n_node = state.next()
            n_eclass = self[n_id]
            # Match the pattern on the compatible children
            if n_eclass.size == n_node.size:
              if isinstance(n_node, WordPlaceholder):
                key = n_node.key
                if key not in state.environment:
                  state.environment[key] = n_eclass.id
                elif state.environment[key] != n_eclass.id:
                  state = None
              else:
                # Collect all the matching enodes
                matching_enodes = []
                for enode in n_eclass.nodes:
                  if enode.key == n_node.key:
                    matching_enodes.append(enode)
                # If we matched some enodes
                if matching_enodes:
                  # Fork the state for all but one matched enodes
                  for enode in matching_enodes[1:]:
                    forked_state = state.fork()
                    forked_state.update(list(enode.children), list(n_node.children))
                    worklist.append(forked_state)
                  # Update the current state
                  state.update(list(matching_enodes[0].children), list(n_node.children))
                else:
                  state = None
            else:
              state = None
    # Return the matches
    return matches

  def check_memo(self):
    test_memo = {}
    for id, eclass in self.classes.items():
      assert eclass.id == id
      for enode in eclass.nodes:
        old_id = test_memo.get(enode, None)
        test_memo[enode] = id
        if old_id is not None:
          assert self.find(old_id) == self.find(id)
    for enode, id in test_memo.items():
      assert id == self.find(id)
      assert id == self.find(self.memo.get(enode))

  def check_eclasses(self):
    for eclass in self.eclasses():
      eclass.assert_unique_leaves()

  def view(self):
    def format_record(x):
      if isinstance(x, list):
        return '{' + '|'.join(format_record(e) for e in x) + '}'
      else:
        return x

    def escape(x):
      return str(x).replace("<", "\\<").replace(">", "\\>")

    g = Digraph(node_attr={'shape': 'record', 'height': '.1'})
    for eclass in self.eclasses():
      g.node(f'{eclass.id}', label=f'e{eclass.id}', shape='circle')
      for enode in eclass.nodes:
        enode_id = str(id(enode))
        g.edge(f'{eclass.id}', enode_id)
        record = [escape(f'{enode.id}:{enode.key}')]
        for i, child in enumerate(enode.children):
          g.edge(f'{enode_id}:p{i}', f'{child}')
          record.append(f'<p{i}>')
        g.node(enode_id, label='|'.join(record))
    g.format = 'png'
    g.layout = 'fdp'
    g.view()

