def evaluate_rpn(rpn, values, mask):
  stack = []
  i = 0
  while i < len(rpn):
    c = rpn[i]
    if c == '+':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append((op1 + op0) & mask)
    elif c == '-':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append((op1 - op0) & mask)
    elif c == '*':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append((op1 * op0) & mask)
    elif c == '&':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append((op1 & op0) & mask)
    elif c == '|':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append((op1 | op0) & mask)
    elif c == '^':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append((op1 ^ op0) & mask)
    elif c == '<':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append((op1 << op0) & mask)
    elif c == '>':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append(LShr(op1, op0, mask) & mask)
    elif c == '~':
      op0 = stack.pop()
      stack.append((~op0) & mask)
    elif c == ':':
      op0 = stack.pop()
      stack.append((-op0) & mask)
    elif c in values:
      stack.append(values[c])
    elif c == 'k':
      number = f'{rpn[i+1]}{rpn[i+2]}{rpn[i+3]}{rpn[i+4]}{rpn[i+5]}{rpn[i+6]}{rpn[i+7]}{rpn[i+8]}{rpn[i+9]}{rpn[i+10]}{rpn[i+11]}{rpn[i+12]}{rpn[i+13]}{rpn[i+14]}{rpn[i+15]}{rpn[i+16]}'
      number = int(number, 16)
      stack.append(number & mask)
      i += 16
    else:
      print(f'evaluate_rpn (rpn = {rpn}): unsupported symbol @ {i} "{c}"')
      input()
    i += 1
  return stack.pop()

def rpn_to_size(rpn):
  s = 0
  i = 0
  while i < len(rpn):
    c = rpn[i]
    if c == 'k':
      i += 16
    else:
      i += 1
    s += 1
  return s

def rpn_to_exp(rpn):
  stack = []
  for c in rpn:
    if c in ['+', '-', '*', '&', '|', '^']:
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append(f'({op1}{c}{op0})')
    elif c in ['~', ':']:
      if c == ':':
        c = '-'
      op0 = stack.pop()
      stack.append(f'({c}{op0})')
    elif c == '<':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append(f'({op1}<<{op0})')
    elif c == '>':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append(f'({op1}>>{op0})')
    elif c in z3_variables:
      stack.append(c)
    else:
      print(f'rpn_to_exp: unsupported symbol "{c}"')
      exit(1)
  return stack.pop()

def rpn_to_z3(rpn, z3_variables, size):
  stack = []
  i = 0
  while i < len(rpn):
    c = rpn[i]
    if c == '+':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append(op1 + op0)
    elif c == '-':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append(op1 - op0)
    elif c == '*':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append(op1 * op0)
    elif c == '&':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append(op1 & op0)
    elif c == '|':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append(op1 | op0)
    elif c == '^':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append(op1 ^ op0)
    elif c == '<':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append(op1 << op0)
    elif c == '>':
      op0 = stack.pop()
      op1 = stack.pop()
      stack.append(LShR(op1, op0))
    elif c == '~':
      op0 = stack.pop()
      stack.append(~op0)
    elif c == ':':
      op0 = stack.pop()
      stack.append(-op0)
    elif c in z3_variables:
      stack.append(z3_variables[c])
    elif c == 'k':
      number = f'{rpn[i+1]}{rpn[i+2]}{rpn[i+3]}{rpn[i+4]}{rpn[i+5]}{rpn[i+6]}{rpn[i+7]}{rpn[i+8]}{rpn[i+9]}{rpn[i+10]}{rpn[i+11]}{rpn[i+12]}{rpn[i+13]}{rpn[i+14]}{rpn[i+15]}{rpn[i+16]}'
      number = int(number, 16)
      stack.append(BitVecVal(number, size))
      i += 16
    else:
      print(f'rpn_to_z3 (rpn = {rpn}): unsupported symbol @ {i} "{c}"')
      input()
    i += 1
  return stack.pop()

def DoCEGIS(expression, template_expression, symbolic_variables, constant_variables, inputs, outputs, output_size, iterations=100):
  global CEGIS_QUERIES
  CEGIS_QUERIES += 1
  # Use two separate solvers for the ForAll-Implies and Counter-Example
  solver_for_all_implies, solver_counter_example = Solver(), Solver()
  # Set a limit to the solvers
  retry = 6
  timeout = 100
  solver_for_all_implies.set('timeout', timeout)
  solver_counter_example.set('timeout', timeout)
  # Keep track of the synthesized constants
  synthesized_constants = []
  # Keep track of the oracle constraints
  oracle_constraints_list = []
  # Create an output variable
  output_variable = BitVec('o', output_size)
  # Define the equivalence to prove
  equivalence = (template_expression == output_variable)
  # Populate the ForAll variables
  for_all_variables = [ output_variable ]
  for symbolic_variable in symbolic_variables:
    for_all_variables.append(symbolic_variable)
  # Add the I/O constraints
  for input_values, output_value in zip(inputs, outputs):
    # Add the output constraint
    io_constraints_list = []
    io_constraints_list.append((output_variable == BitVecVal(output_value, output_size)))
    # Add the input constraints
    for input_variable, input_value in input_values:
      io_constraints_list.append((input_variable == BitVecVal(input_value, input_variable.size())))
    # Update the oracle constraints
    oracle_constraints_list.append(And(io_constraints_list))
  # Execute the CEGIS loop
  for i in range(iterations):
    # Define the ForAll-Implies query
    implication = Implies(Or(oracle_constraints_list), equivalence)
    for_all_query = ForAll(for_all_variables, implication)
    # Add the ForAll-Implies query
    solver_for_all_implies.add(for_all_query)
    # Verify if it's satisfiable
    solver_result = solver_for_all_implies.check()
    if solver_result == sat:
      # Reset the Counter-Example solver and saved constants
      synthesized_constants.clear()
      solver_counter_example.reset()
      # Define the Counter-Example query
      counter_example = (expression != template_expression)
      # Add the Counter-Example query
      solver_counter_example.add(counter_example)
      # Extract the solutions from the model
      model_for_all_implies = solver_for_all_implies.model()
      for constant_variable in constant_variables:
        solution_value = model_for_all_implies[constant_variable]
        # Add the variable-constant equivalence
        solver_counter_example.add(constant_variable == solution_value)
        # Save the variable-constant equivalence
        synthesized_constants.append((constant_variable, solution_value))
      # Determine if a Counter-Example exists
      solver_result = solver_counter_example.check()
      if solver_result == sat:
        # Fetch the Counter-Example model
        model_counter_example = solver_counter_example.model()
        # Get the output value given the Counter-Example inputs
        counter_example_output = model_counter_example.eval(expression)
        # Add the new output constraint
        counter_example_constraints = []
        counter_example_constraints.append((output_variable == counter_example_output))
        # We can enrich the I/O pair constraints
        for symbolic_variable in symbolic_variables:
          # Fetch the solution value
          solution_value = model_counter_example[symbolic_variable]
          # Add the variable-constant equivalence
          counter_example_constraints.append(symbolic_variable == solution_value)
        # Update the oracle constraints
        oracle_constraints_list.append(And(counter_example_constraints))
      elif TREAT_UNKNOWN_AS_UNSAT and (solver_result == unknown):
        # We assume we've properly synthesized the constants
        # print(f"CEGIS(unknown): template_expression = {template_expression}, expression = {expression}, synthesized_constants = {synthesized_constants}")
        return True, synthesized_constants
      elif solver_result == unsat:
        # We properly synthesized the constants
        # print(f"CEGIS(unsat): template_expression = {template_expression}, expression = {expression}, synthesized_constants = {synthesized_constants}")
        return True, synthesized_constants
      else:
        # We probably ran into an error
        return False, synthesized_constants
    elif solver_result == unsat:
      # We surely got a wrong template
      # print(f'Wrong template: {template_expression}')
      break
    elif solver_result == unknown:
      # Probably got a good template, but we reached the timeout
      print(f'Timeout reached, retry ({retry}): {template_expression}')
      timeout *= 2
      retry -= 1
      if retry == 0:
        break
  # Notify about the failure
  return False, synthesized_constants

def is_equivalent(expression0, expression1, reason='unknown', silent=True):
  solver = Solver()
  solver.set('timeout', Z3_TIMEOUT)
  solver.add(expression0 != expression1)
  if TREAT_UNKNOWN_AS_UNSAT:
    result = solver.check() in [unsat, unknown]
  else:
    result = solver.check() == unsat
  if not result and not silent:
    print(f'{reason}: (({expression0}) != ({expression1})) => {result}')
  return result

