class NodeSiMBAWeight:

  def __init__(self, egraph, size, verify, inject, use_constants_dnf_rewriting, use_sympy_simplify_logic):
    self.size = size
    self.egraph = egraph
    self.verify = verify
    self.inject = inject
    self.constants = set()
    self.variables = {}
    self.injectable = {}
    self.equivalence = {}
    self.use_constants_dnf_rewriting = use_constants_dnf_rewriting
    self.use_sympy_simplify_logic = use_sympy_simplify_logic

  def cost(self, eclass, enode, expression, symbols):
    # Do not process constants or variables
    if (not isinstance(expression, WordConstant)) and (not isinstance(expression, WordVariable)):
      # Handle the complex cases
      simplified_expressions = simplify_with_simba(expression, self.size, self.constants, self.use_constants_dnf_rewriting, self.use_sympy_simplify_logic)
      # Check if we didn't manage to simplify the expression
      if not simplified_expressions:
        return math.inf
      # Loop the simplified expressions and detect the smallest size
      best_size = math.inf
      for simplified in simplified_expressions:
        # Wrap a constant into a WordConstant
        if isinstance(simplified, int):
          simplified &= (2**self.size-1)
          simplified = WordConstant(simplified)
        # Verify the correctness with several random samples
        correct = True
        for j in range(5):
          values = {}
          for symbol in symbols.keys():
            values[symbol] = random.getrandbits(self.size)
          i = expression.evaluate(values, 2**self.size-1)
          o = simplified.evaluate(values, 2**self.size-1)
          if i != o:
            correct = False
            break
        if correct:
          # Verify the correctness with Z3
          if len(self.variables) == 0:
            for symbol in symbols.keys():
              self.variables[symbol] = BitVec(symbol, self.size)
          i_z3 = None
          o_z3 = None
          if self.verify:
            i_z3 = rpn_to_z3(expression.to_rpn(), self.variables, self.size)
            o_z3 = rpn_to_z3(simplified.to_rpn(), self.variables, self.size)
          if (not self.verify) or is_equivalent(i_z3, o_z3):
            # Compute the proper expression size
            simplified_size = simplified.get_node_cost()
            # Mark the expression as injectable
            if eclass.id not in self.injectable:
              self.injectable[eclass.id] = []
            self.injectable[eclass.id].append((simplified, {}, simplified_size))
            # Store the size if it's the best so far
            if simplified_size < best_size:
              best_size = simplified_size
      return best_size
    # We have ignored the node or failed the simplification
    return math.inf

  def delete_if_scheduled_for_injection(self, id):
    if self.inject and id in self.injectable:
      del self.injectable[id]

  def get_injectable(self):
    return self.injectable

  def get_equivalence(self):
    equivalences = []
    for vars_key, oracle_map in self.equivalence.items():
      for oracle_key, eclass_map in oracle_map.items():
        if len(eclass_map) > 1:
          equivalences.append(eclass_map)
    return equivalences

  def get_constants(self):
    return self.constants

