class Extractor:

  def __init__(self, egraph, id, functions, symbols, harvesting=False, debug=False):
    self.harvesting = harvesting
    self.functions = functions
    self.symbols = symbols
    self.egraph = egraph
    self.debug = debug
    self.costs = {}  # HashMap<Id, (CF::Cost, L)>
    self.expressions = {}
    self.constants = set()
    self.find_costs(id)

  def update_costs(self, id, debug=False):
    # Obtain the updated eclass id
    head = self.egraph[id]
    # Fetch the eclasses
    eclasses = self.egraph.eclasses()
    if self.debug:
      print(f'eclasses #: {len(eclasses)}')
    # Compute the size costs again
    self.costs = {}
    updated = True
    while updated:
      updated = False
      for eclass in self.egraph.eclasses():
        new_values = self.make_pass(eclass)
        cur_values = self.costs.get(eclass.id, None)
        if not cur_values and new_values:
          self.costs[eclass.id] = new_values
          updated = True
        elif cur_values and new_values:
          if new_values[0] < cur_values[0]:
            self.costs[eclass.id] = new_values
            updated = True
    # Verify if all the costs have been computed
    for eclass in eclasses:
      assert eclass.id in self.costs
      assert self.costs[eclass.id][0] != math.inf
    # Extract the constants
    if self.harvesting:
      for eclass in eclasses:
        cost, node, _ = self.costs[eclass.id]
        if cost == 1 and node.key.startswith('K_'):
          constant = int(node.key.replace('K_', ''), 16)
          self.constants.add(constant)

  def find_best(self, top_id):
    # Obtain the updated id
    top_id = self.egraph.find(top_id)
    # Obtain the best cost/node
    worklist = [ (False, top_id) ]
    known = set()
    nodes = {}
    while worklist:
      done, node_id = worklist.pop()
      node_id = self.egraph.find(node_id)
      if done:
        cost, curr, synthesizable = self.costs[node_id]
        if curr.key == 'MulW':
          child0 = nodes[self.egraph.find(curr.children[0])][1]
          child1 = nodes[self.egraph.find(curr.children[1])][1]
          node = child0 * child1
          node.set_synthesizable(synthesizable)
        elif curr.key == 'ShlW':
          child0 = nodes[self.egraph.find(curr.children[0])][1]
          child1 = nodes[self.egraph.find(curr.children[1])][1]
          node = child0 << child1
          node.set_synthesizable(synthesizable)
        elif curr.key == 'ShrW':
          child0 = nodes[self.egraph.find(curr.children[0])][1]
          child1 = nodes[self.egraph.find(curr.children[1])][1]
          node = child0 >> child1
          node.set_synthesizable(synthesizable)
        elif curr.key == 'AddW':
          child0 = nodes[self.egraph.find(curr.children[0])][1]
          child1 = nodes[self.egraph.find(curr.children[1])][1]
          node = child0 + child1
          node.set_synthesizable(synthesizable)
        elif curr.key == 'SubW':
          child0 = nodes[self.egraph.find(curr.children[0])][1]
          child1 = nodes[self.egraph.find(curr.children[1])][1]
          node = child0 - child1
          node.set_synthesizable(synthesizable)
        elif curr.key == 'AndW':
          child0 = nodes[self.egraph.find(curr.children[0])][1]
          child1 = nodes[self.egraph.find(curr.children[1])][1]
          node = child0 & child1
          node.set_synthesizable(synthesizable)
        elif curr.key == 'XorW':
          child0 = nodes[self.egraph.find(curr.children[0])][1]
          child1 = nodes[self.egraph.find(curr.children[1])][1]
          node = child0 ^ child1
          node.set_synthesizable(synthesizable)
        elif curr.key == 'OrW':
          child0 = nodes[self.egraph.find(curr.children[0])][1]
          child1 = nodes[self.egraph.find(curr.children[1])][1]
          node = child0 | child1
          node.set_synthesizable(synthesizable)
        elif curr.key == 'NegW':
          child0 = nodes[self.egraph.find(curr.children[0])][1]
          node = -child0
          node.set_synthesizable(synthesizable)
        elif curr.key == 'NotW':
          child0 = nodes[self.egraph.find(curr.children[0])][1]
          node = ~child0
          node.set_synthesizable(synthesizable)
        elif curr.key.startswith('WV_'):
          node = WordVariable(curr.key.replace('WV_', ''))
        elif curr.key.startswith('K_'):
          node = WordConstant(curr.key)
        else:
          print(f'Unsopported node: {curr.key}')
          input()
        # Recompute the cost
        nodes[node_id] = (node.get_node_cost(), node)
      else:
        if node_id in known:
          continue
        known.add(node_id)
        _, node, _ = self.costs[node_id]
        worklist.append((True, node_id))
        for child_id in node.children:
          worklist.append((False, self.egraph.find(child_id)))
    # Return the best cost/node
    return nodes[top_id]

  def find_costs(self, id):
    # Obtain the updated eclass id
    head = self.egraph[id]
    # Fetch the eclasses
    eclasses = self.egraph.eclasses()
    if self.debug:
      print(f'eclasses #: {len(eclasses)}')
    # 1. Compute the plain AST size costs
    updated = True
    while updated:
      updated = False
      for eclass in self.egraph.eclasses():
        new_values = self.make_pass(eclass)
        cur_values = self.costs.get(eclass.id, None)
        if not cur_values and new_values:
          self.costs[eclass.id] = new_values
          updated = True
        elif cur_values and new_values:
          if new_values[0] < cur_values[0]:
            self.costs[eclass.id] = new_values
            updated = True
    # Verify if all the AST size costs have been computed
    for eclass in eclasses:
      assert eclass.id in self.costs
      assert self.costs[eclass.id][0] != math.inf
    # 2. Compute the simplified AST size costs
    if self.functions:
      known = set()
      updated = True
      best_costs = {}
      while updated:
        updated = False
        # Loop all the eclasses
        for eclass in eclasses:
          if eclass.id in known:
            continue
          # Check if we can simplify the node
          computable = True
          for child_id in eclass.nodes[0].children:
            if child_id not in known:
              computable = False
              break
          # Try simplifying the node
          if computable:
            # Obtain the size cost
            min_cost, min_node, synthesizable = self.costs[eclass.id]
            # Compute the simplified cost, we have 3 options:
            # - select the min_node (fast, but may not be deterministic)
            # - select the cur_node at position 0 (may select a big AST, so slower, probably deterministic)
            # - calculate the simplified cost of all nodes, as some intermediate variables may affect some more than others (slow)
            cur_node = eclass.nodes[0]
            cur_cost = math.inf
            cur_expr = self.find_best(eclass.id)[1]
            for function in self.functions:
              calculated_cost = function.cost(eclass, cur_node, cur_expr, self.symbols)
              # Extract the harvested constants
              if self.harvesting:
                self.constants = self.constants.union(function.get_constants())
              # Save the best cost computed by a cost function
              if calculated_cost < cur_cost:
                cur_cost = calculated_cost
            # Store the expression
            self.expressions[eclass.id] = cur_expr
            # Determine if the cost computed by a cost function is better than the known size cost
            if cur_cost < min_cost:
              # Save the computed cost
              best_costs[eclass.id] = (cur_cost, cur_node, True)
            else:
              # TODO: execute this even if the cost improved and deleted all but the best expression to be injected
              for function in self.functions:
                function.delete_if_scheduled_for_injection(eclass.id)
            # Mark it as known
            known.add(eclass.id)
            # Mark it as updated
            updated = True
      # Store the new best costs
      for eclass_id, best_values in best_costs.items():
        self.costs[eclass_id] = best_values
      # 3. Update the final costs
      for eclass in self.egraph.eclasses():
        min_cost, min_node, synthesizable = self.costs[eclass.id]
        for cur_node in eclass.nodes:
          cur_cost = self.node_size_cost(cur_node)
          if cur_cost < min_cost:
            min_cost = cur_cost
            min_node = cur_node
            # TODO: move this outside of the loop
            self.costs[eclass.id] = (min_cost, min_node, False)
            for function in self.functions:
              function.delete_if_scheduled_for_injection(eclass.id)
    # 4. Extract the constants
    if self.harvesting:
      for eclass in eclasses:
        cost, node, _ = self.costs[eclass.id]
        if (cost == 1) and node.key.startswith('K_'):
          constant = int(node.key.replace('K_', ''), 16)
          self.constants.add(constant)

  def node_size_cost(self, enode):
    # Verify if we can compute the cost
    for id in enode.children:
      if id not in self.costs:
        return math.inf
    # Compute the cost
    return 1 + sum([self.costs[id][0] for id in enode.children])

  def make_pass(self, eclass):
    # First we determine the smallest representation size of this node
    min_cost, min_node = math.inf, None
    for cur_node in eclass.nodes:
      cur_cost = self.node_size_cost(cur_node)
      if cur_cost < min_cost:
        min_cost = cur_cost
        min_node = cur_node
    # Return the best code and node
    return (min_cost, min_node, False)

  def get_harvested_constants(self, harvested_constants):
    return self.constants.difference(harvested_constants)

  def get_eclass_expressions(self):
    expressions = self.expressions
    self.expressions = {}
    return expressions

