class Rule:

  def __init__(self, lhs, rhs, name=""):
    self.lhs = lhs
    self.rhs = rhs
    self.name = name

  def __repr__(self):
    return f'{self.lhs} -> {self.rhs}'

def prove_rewriting_rules():
  size = 4
  placeholders = {
    'x': BitVec('x', size),
    'y': BitVec('y', size),
    'z': BitVec('z', size),
  }
  solver = Solver()
  for rule in rules:
    rpn_lhs = rule.lhs.to_rpn()
    z3_lhs = rpn_to_z3(rpn_lhs, placeholders, size)
    for rewrite in rule.rhs:
      rpn_rewrite = rewrite.to_rpn()
      z3_rhs = rpn_to_z3(rpn_rewrite, placeholders, size)
      solver.push()
      solver.add(z3_lhs != z3_rhs)
      if solver.check() == sat:
        print(f'Wrong rewriting rule: {rule.lhs} -> {rewrite}')
        exit(1)
      solver.pop()

# ================================================================================================================

def apply_rules(egraph, rules, iteration, debug=False):
  changed = False
  matches = []
  for rule in rules:
    for eclass, environment in egraph.ematch(rule.lhs):
      matches.append((eclass, environment, rule))
  for eclass, environment, rule in matches:
    for replacement in rule.rhs:
      new_eclass = egraph.add_instantiation(replacement, environment)
      egraph.union(new_eclass, eclass)
      if eclass != new_eclass:
        changed = True
        if debug:
          print(f'{eclass} MATCHED {rule.lhs} -> {replacement} identified by {new_eclass} with {environment}')
  egraph.rebuild()
  return changed

