class ASTEntry:

  def __init__(self):
    self.ast = None

  def get(self):
    stack = []
    i = 0
    while i < len(self.ast):
      c = self.ast[i]
      if c == '+':
        op0 = stack.pop()
        op1 = stack.pop()
        stack.append(op1 + op0)
      elif c == '-':
        op0 = stack.pop()
        op1 = stack.pop()
        stack.append(op1 - op0)
      elif c == '*':
        op0 = stack.pop()
        op1 = stack.pop()
        stack.append(op1 * op0)
      elif c == '&':
        op0 = stack.pop()
        op1 = stack.pop()
        stack.append(op1 & op0)
      elif c == '^':
        op0 = stack.pop()
        op1 = stack.pop()
        stack.append(op1 ^ op0)
      elif c == '|':
        op0 = stack.pop()
        op1 = stack.pop()
        stack.append(op1 | op0)
      elif c == '<':
        op0 = stack.pop()
        op1 = stack.pop()
        stack.append(op1 << op0)
      elif c == '>':
        op0 = stack.pop()
        op1 = stack.pop()
        stack.append(op1 >> op0)
      elif c == '~':
        op0 = stack.pop()
        stack.append(~op0)
      elif c == ':':
        op0 = stack.pop()
        stack.append(-op0)
      elif c == 'k':
        stack.append(WordConstant(f'K_{self.ast[i+1]}{self.ast[i+2]}{self.ast[i+3]}{self.ast[i+4]}{self.ast[i+5]}{self.ast[i+6]}{self.ast[i+7]}{self.ast[i+8]}{self.ast[i+9]}{self.ast[i+10]}{self.ast[i+11]}{self.ast[i+12]}{self.ast[i+13]}{self.ast[i+14]}{self.ast[i+15]}{self.ast[i+16]}'))
        i += 16
      else:
        stack.append(WordVariable(c))
      i += 1
    result = stack.pop()
    return result

class OracleDB:

  def __init__(self):
    self.input = []  # [ { terminator: value } ]
    self.oracle = {} # { size: { hash : [ ASTEntry ] } }
    self.constants = {} # { size: { hash : [ ASTEntry ] } }

def load_oracle(path, use_constants=False):
  with open(path, 'r') as file:
    # Create the oracle
    oracle = OracleDB()
    # Initialize the sizes
    oracle.oracle[64] = {}
    oracle.constants[64] = {}
    # Read the inputs
    values = {}
    for line in file.readlines():
      line = line.strip()
      if '-----' in line:
        if values:
          oracle.input.append(values)
        values = {}
      elif ' = ' in line:
        splitted = line.split(' = ')
        variable = splitted[0]
        value = int(splitted[1], 16)
        values[variable] = value
      elif ' -> ' in line:
        if 'K' in line and not use_constants:
          continue
        splitted = line.split(' -> ')
        key = int(splitted[0], 16)
        count = splitted[1]
        expressions = splitted[2]
        expressions = expressions.replace('[ ', '')
        expressions = expressions.replace(' ]', '')
        expressions = expressions.split(' ')
        entries = []
        for expression in expressions:
          entry = ASTEntry()
          entry.ast = expression
          entries.append(entry)
        if 'K' in line:
          oracle.constants[64][key] = entries
        else:
          oracle.oracle[64][key] = entries
    # Return the oracle
    return oracle
  return None

