def strip_opaque_variables_internal(expression, verify, bits, samples):
  did_update = False
  # Clone the original expression
  original = copy.deepcopy(expression)
  # Compute the bit mask
  mask = 2**bits-1
  # Collect the used variables
  worklist = [ expression ]
  known = set()
  variables = set()
  while worklist:
    node = worklist.pop()
    if node in known:
      continue
    known.add(node)
    if node.key.startswith('WV_'):
      variables.add(node.key.replace('WV_', ''))
    for child in node.children:
      worklist.append(child)
  # Calculate N random inputs
  inputs = []
  for i in range(samples):
    values = {}
    for v in variables:
      values[v] = random.getrandbits(bits)
    inputs.append(values)
  # Evaluate the expression N times
  outputs = []
  for values in inputs:
    outputs.append(expression.evaluate(values, mask))
  # Evaluate the expression N times, with a changed variable
  opaque = set()
  for v in variables:
    # Compute the outputs
    evaluation = []
    for values in inputs:
      copied = {}
      for key, val in values.items():
        if key != v:
          copied[key] = val
        else:
          copied[key] = random.getrandbits(bits)
      evaluation.append(expression.evaluate(copied, mask))
    # Check if we got the same outputs
    different = False
    for o0, o1 in zip(outputs, evaluation):
      if o0 != o1:
        different = True
        break
    # If the outputs are the same, mark the variable as possibly opaque
    if not different:
      opaque.add(v)
  # Replace the opaque variables with a zero constant
  updated = expression
  if opaque:
    print(f'Possibly opaque variable(s) found: {opaque}')
    worklist = [ (False, expression) ]
    known = set()
    nodes = {}
    while worklist:
      done, node = worklist.pop()
      if done:
        if node.key.startswith('WV_'):
          name = node.key.replace('WV_', '')
          if name in opaque:
            nodes[node] = WordConstant(0)
            did_update = True
        for index, child in enumerate(node.children):
          if child in nodes:
            node.children[index] = nodes[child]
      else:
        worklist.append((True, node))
        for child in node.children:
          worklist.append((False, child))
    # Verify the correctness with z3
    if verify:
      symbolic_variables = {}
      for v in variables:
        symbolic_variables[v] = BitVec(v, bits)
      rpn_0 = original.to_rpn()
      rpn_1 = updated.to_rpn()
      z3_0 = rpn_to_z3(rpn_0, symbolic_variables, bits)
      z3_1 = rpn_to_z3(rpn_1, symbolic_variables, bits)
      if opaque and not is_equivalent(z3_0, z3_1):
        return did_update, original
  # Return the updated expression
  return did_update, updated

def strip_opaque_variables(expression, verify, bits, samples=30):
  worklist = [ (False, expression) ]
  stripped = {}
  # Update the node
  while worklist:
    done, node = worklist.pop()
    if done:
      # Update it with the simplified children
      for index, child in enumerate(node.children):
        if child in stripped:
          node.children[index] = stripped[child]
      # Try stripping more variables
      did_update, updated_node = strip_opaque_variables_internal(node, verify, bits, samples)
      if did_update:
        stripped[node] = updated_node
    else:
      worklist.append((True, node))
      for child in node.children:
        worklist.append((False, child))
  # Return the updated expression
  return expression

def explode_multiplication(expression, bound=255):
  worklist = [ (False, expression) ]
  known = set()
  nodes = {}
  while worklist:
    done, node = worklist.pop()
    if done:
      # Replace the children if previously expanded
      for index, child in enumerate(node.children):
        if child in nodes:
          node.children[index] = nodes[child]
      # Expand the children if needed
      if node.key == 'MulW':
        child0 = node.children[0]
        child1 = node.children[1]
        if child0.key.startswith('K_') and not child1.key.startswith('K_'):
          amount = int(child0.key.replace('K_', ''), 16) - 2
          if amount >= 0 and amount < bound:
            expansion = child1 + child1
            for i in range(amount):
              expansion = expansion + child1
            nodes[node] = expansion
        elif not child0.key.startswith('K_') and child1.key.startswith('K_'):
          amount = int(child1.key.replace('K_', ''), 16) - 2
          if amount >= 0 and amount < bound:
            expansion = child0 + child0
            for i in range(amount):
              expansion = expansion + child0
            nodes[node] = expansion
    else:
      worklist.append((True, node))
      for child in node.children:
        worklist.append((False, child))
  return expression

def simplify_identity_node(expression):
  simplified = True
  nodes = {}
  while simplified:
    simplified = False
    worklist = [ (False, expression) ]
    known = set()
    while worklist:
      done, node = worklist.pop()
      if done:
        # Replace the children if previously expanded
        for index, child in enumerate(node.children):
          if child in nodes:
            node.children[index] = nodes[child]
            simplified = True
        # Expand the children if needed
        if node.key == 'MulW':
          child0 = node.children[0]
          child1 = node.children[1]
          if child0.key.startswith('K_'):
            number = int(child0.key.replace('K_', ''), 16)
            if number == 1:
              nodes[node] = child1
            elif number == 0:
              nodes[node] = child0
          elif child1.key.startswith('K_'):
            number = int(child1.key.replace('K_', ''), 16)
            if number == 1:
              nodes[node] = child0
            elif number == 0:
              nodes[node] = child1
        elif node.key in ['AddW', 'XorW', 'OrW']:
          child0 = node.children[0]
          child1 = node.children[1]
          if child0.key.startswith('K_'):
            number = int(child0.key.replace('K_', ''), 16)
            if number == 0:
              nodes[node] = child1
          elif child1.key.startswith('K_'):
            number = int(child1.key.replace('K_', ''), 16)
            if number == 0:
              nodes[node] = child0
        elif node.key in ['AndW']:
          child0 = node.children[0]
          child1 = node.children[1]
          if child0.key.startswith('K_'):
            number = int(child0.key.replace('K_', ''), 16)
            if number == 0:
              nodes[node] = child0
          elif child1.key.startswith('K_'):
            number = int(child1.key.replace('K_', ''), 16)
            if number == 0:
              nodes[node] = child1
        elif node.key == 'SubW':
          child0 = node.children[0]
          child1 = node.children[1]
          if child1.key.startswith('K_'):
            number = int(child1.key.replace('K_', ''), 16)
            if number == 0:
              nodes[node] = child0
        elif node.key == 'NegW':
          child0 = node.children[0]
          if child0.key.startswith('K_'):
            number = int(child0.key.replace('K_', ''), 16)
            if number == 0:
              nodes[node] = child0
        elif node.key == 'NotW':
          child0 = node.children[0]
          if child0.key.startswith('K_'):
            number = int(child0.key.replace('K_', ''), 16)
            if number == 0:
              nodes[node] = WordConstant(0xffffffffffffffff)
      else:
        worklist.append((True, node))
        for child in node.children:
          worklist.append((False, child))
  if expression in nodes:
    expression = nodes[expression]
  return expression

def negate_constant_node(expression, mask, bits):
  worklist = [ (False, expression) ]
  known = set()
  nodes = {}
  while worklist:
    done, node = worklist.pop()
    if done:
      # Replace the children if previously expanded
      for index, child in enumerate(node.children):
        if child in nodes:
          node.children[index] = nodes[child]
      # Expand the children if needed
      if node.key.startswith('K_'):
        number = int(node.key.replace('K_', ''), 16)
        if (number >> (bits - 1)) & 1:
          number = ((2**bits-1) - number + 1) & mask
          nodes[node] = -WordConstant(number)
    else:
      worklist.append((True, node))
      for child in node.children:
        worklist.append((False, child))
  return expression

