class LLVMTranslator:

  def __init__(self, bit_count, expression):
    self.bit_count = bit_count
    self.expression = expression
    self.module = ir.Module(name="Module")
    self.function = self.__ast_to_ir()

  def __ast_to_ir(self):
    # Create the function type
    int_type = ir.IntType(self.bit_count)
    # Get the amount of variables
    variables = self.expression.variables
    variables_count = len(variables)
    # Define the function type
    function_type = ir.FunctionType(int_type, [int_type] * variables_count)
    # Generate the function declaration
    function = ir.Function(self.module, function_type, name="Function")
    # Implement the function body
    entry = function.append_basic_block(name="Entry")
    builder = ir.IRBuilder(entry)
    # Translate the AST to LLVM-IR
    worklist = [ (self.expression, False) ]
    arguments = {}
    values = {}
    while worklist:
      # Fetch the node and its state
      node, done = worklist.pop()
      # Skip if known
      if node in values:
        continue
      # Determine if we need to translate it
      if done:
        if isinstance(node, WordConstant):
          values[node] = ir.Constant(int_type, node.evaluate({}, 0))
        elif isinstance(node, WordVariable):
          var = node.get_name()
          if var not in arguments:
            arguments[var] = len(arguments)
          values[node] = function.args[arguments[var]]
        elif isinstance(node, NotW):
          values[node] = builder.not_(values[node.children[0]])
        elif isinstance(node, NegW):
          values[node] = builder.neg(values[node.children[0]])
        elif isinstance(node, AddW):
          values[node] = builder.add(values[node.children[0]], values[node.children[1]])
        elif isinstance(node, SubW):
          values[node] = builder.sub(values[node.children[0]], values[node.children[1]])
        elif isinstance(node, MulW):
          values[node] = builder.mul(values[node.children[0]], values[node.children[1]])
        elif isinstance(node, AndW):
          values[node] = builder.and_(values[node.children[0]], values[node.children[1]])
        elif isinstance(node, XorW):
          values[node] = builder.xor(values[node.children[0]], values[node.children[1]])
        elif isinstance(node, OrW):
          values[node] = builder.or_(values[node.children[0]], values[node.children[1]])
        elif isinstance(node, ShlW):
          values[node] = builder.shl(values[node.children[0]], values[node.children[1]])
        elif isinstance(node, ShrW):
          values[node] = builder.lshr(values[node.children[0]], values[node.children[1]])
        else:
          raise Exception(f"Unsupported node type: {node.key}")
      else:
        worklist.append((node, True))
        for child in node.children:
          worklist.append((child, False))
    # Add the return instruction
    builder.ret(values[self.expression])
    # Return the generated function
    return function

  def __ir_to_ast(self):
    pass

  def optimize(self):
    # Optimize the module with -O3
    pmb = binding.PassManagerBuilder()
    pmb.opt_level = 3
    pmb.size_level = 2
    mpm = binding.ModulePassManager()
    pmb.populate(mpm)
    module_ref = binding.parse_assembly(str(self.module))
    # Bail out if the optimization didn't work
    if not mpm.run(module_ref):
      return False, self.expression
    # Translate the LLVM-IR back to an AST
    print(f"module: {module_ref}")
    # Return the optimized expression
    return True, self.expression

def simplify_with_llvm(expression, bit_count):
  translator = LLVMTranslator(bit_count, expression)
  return translator.optimize()

# ================================================================================================================

def bruteforce_verification(expression, values, ground_truth, mask):
  for i in range(len(values)):
    if expression.evaluate(values[i], mask) != ground_truth[i]:
      return False
  return True

