  # expression = ((((((z&((x&0x208020b6)&w))*0x7e17c56b5ea3b170)+(((z&0x36bcf879b6)&w)*0xc104435b248f5c97))+(0xffefd9ef2c1ecab1*((w&0x369c7b5940)-((z|0x36bcf879b6)&(~(z^(w^0x36bcf879b6)))))))+(((((x&0x369c7b5940)*0xc0f41d4a50ae2748)+0xb8535a448db7ab58)+(0x1f85f15ad7a8ec5c*((x^(z&0xffffffc96384a6bf))+(x^(w&0x208020b6)))))+(((w&(z&0x369c785900))*0x3f0be2b5af51d8b8)+(x*0xe08a34b5fc3848f3))))+(y*0xe97b3e410bd8781)) # synth = 72

  expressions = [ expression ]

  times = []

  oracle = None

  for expression in expressions:

    # Calculate a ground truth value to compare against

    mask = 2**args.bits-1
    values = {}
    for i in range(30):
      values[i] = {}
      for symbol in symbols.keys():
        values[i][symbol] = random.getrandbits(args.bits)
    ground_truth = {}
    for i in range(len(values)):
      ground_truth[i] = expression.evaluate(values[i], mask)

    # Print the expression before preprocessing

    egraph = EGraph()
    node = egraph.add_expression(expression)
    extractor = Extractor(egraph, node, [], symbols)
    original_cost, original_node = extractor.find_best(node)
    print(f'Original (cost = {original_cost}): {original_node.to_exp()}')

    # Preprocess the input expression with MBA-Blast

    if args.use_mba_blast_before:
      simplified, success = simplify_with_mba_blast(expression, args.mba_blast_logic, args.bits)
      if success:
        if bruteforce_verification(simplified, values, ground_truth, mask):
          expression = simplified
          # Compute the current cost
          egraph = EGraph()
          node = egraph.add_expression(expression)
          extractor = Extractor(egraph, node, [], symbols)
          preprocessed_cost, preprocessed_node = extractor.find_best(node)
          # Debug print the preprocessing information
          print(f'MBA-Blast (cost = {preprocessed_cost}): {preprocessed_node.to_exp()}')

    # Preprocess the input expression with SiMBA

    if args.use_simba_before:
      ignored_constants = set()
      simplified_expressions = simplify_with_simba(expression, args.bits, ignored_constants, args.use_constants_dnf_rewriting, args.use_sympy_simplify_logic)
      # Check if we've managed to simplify the expression with SiMBA
      if simplified_expressions:
        # Fetch the first expression, which is the one with the lowest size
        simplified = simplified_expressions[0]
        # Verify if the expression is valid
        if bruteforce_verification(simplified, values, ground_truth, mask):
          expression = simplified
          # Compute the current cost
          egraph = EGraph()
          node = egraph.add_expression(expression)
          extractor = Extractor(egraph, node, [], symbols)
          preprocessed_cost, preprocessed_node = extractor.find_best(node)
          # Debug print the preprocessing information
          print(f'SiMBA (cost = {preprocessed_cost}): {preprocessed_node.to_exp()}')

    # Preprocess the input expression with LLVM

    if args.use_llvm_before:
      simplified = simplify_with_llvm(expression, args.bits)
      print(f"simplified: {simplified}")
      if simplified[0] and bruteforce_verification(simplified[1], values, ground_truth, mask):
        expression = simplified[1]
        # Compute the current cost
        egraph = EGraph()
        node = egraph.add_expression(expression)
        extractor = Extractor(egraph, node, [], symbols)
        preprocessed_cost, preprocessed_node = extractor.find_best(node)
        # Debug print the preprocessing information
        print(f'LLVM (cost = {preprocessed_cost}): {preprocessed_node.to_exp()}')

    # Preprocess the input expression
    # TODO: remove these?

    if args.strip_opaque_variables:
      expression = strip_opaque_variables(expression, args.verify, args.bits)
    if args.explode_multiplication:
      expression = explode_multiplication(expression)
    if args.negate_constant_node:
      expression = negate_constant_node(expression, mask, args.bits)
    if args.explode_multiplication:
      expression = explode_multiplication(expression)
    if args.simplify_identity_node:
      expression = simplify_identity_node(expression)

    # Check if the preprocessing broke the expression semantics

    if not bruteforce_verification(expression, values, ground_truth, mask):
      print('Pre-processing broke the expression semantics!')
      exit(1)

    # Load the proper oracle

    if not oracle and args.use_qsynth_inside:
      begin = time.time()
      if args.use_constants_oracle:
        with open('oracle_constant.pickle', 'rb') as file:
          oracle = pickle.load(file)
      else:
        with open('oracle_symbolic.pickle', 'rb') as file:
          oracle = pickle.load(file)
      end = time.time()
      print(f"Loaded the oracle in: {(end-begin):.02f}s")

      # Resize the oracle inputs

      for index, inputs in enumerate(oracle.input):
        masked = {}
        for key, val in inputs.items():
          masked[key] = val & ((2**args.bits)-1)
        oracle.input[index] = masked

    # Start tracking the execution time

    start_time = time.time()

    # Create and populate the e-graph

    egraph = EGraph()
    node = egraph.add_expression(expression)

    # Compute the cost (eventually after preprocessing)

    extractor = Extractor(egraph, node, [], symbols)
    initial_cost, initial_node = extractor.find_best(node)

    # Execute the e-graph saturation + synthesis loop

    done = False
    same_cost = 0
    previous_cost = 0
    original_cost = initial_cost
    harvested_constants = set()
    constants_computation_cache = {}
    for i in range(args.e_graph_steps_count):
      print('='*100)
      if not apply_rules(egraph, rules, i):
        done = True
      # Define the cost functions
      cost_functions = []
      if args.use_simba_inside:
        cost_functions.append(NodeSiMBAWeight(egraph, args.bits, args.verify, args.inject_into_e_graph, args.use_constants_dnf_rewriting, args.use_sympy_simplify_logic))
      if args.use_qsynth_inside:
        cost_functions.append(NodeQSynthWeight(egraph, oracle, args.bits, args.verify, args.inject_into_e_graph))
      # Extract the best node and its cost
      extractor = Extractor(egraph, node, cost_functions, symbols, args.use_constants_harvest)
      # Enrich the e-graph
      for cost_function in cost_functions:
        # Inject the equivalence knowledge into the e-graph
        equivalence = cost_function.get_equivalence()
        if args.merge_into_e_graph and equivalence:
          for eclass_map in equivalence:
            eclass_ids = list(eclass_map.keys())
            head_id = eclass_ids[0]
            head_z3 = eclass_map[head_id]
            for eclass_id in eclass_ids[1:]:
              node_z3 = eclass_map[eclass_id]
              if (not args.verify) or is_equivalent(head_z3, node_z3, ""):
                egraph.union(head_id, eclass_id)
          egraph.rebuild()
          extractor.update_costs(node)
        # Inject the synthesized knowledge into the e-graph
        injectable = cost_function.get_injectable()
        if args.inject_into_e_graph and injectable:
          # Keep track of the new e-class identifiers and their best size
          upper_bound_sizes = {}
          new_eclass_ids = {}
          for old_eclass_id in sorted(injectable.keys()):
            # Check if the size matches the expectations
            if args.verify:
              original_size, original_node = extractor.find_best(old_eclass_id)
              original_node_cost = original_node.get_node_cost()
              upper_bound_size = original_size
              assert original_size == original_node_cost, f"original_size: {original_size}, original_cost: {original_node_cost}"
            # Obtain the simplified nodes
            simplified_nodes = injectable[old_eclass_id]
            for simplified_node, environment, simplified_size in simplified_nodes:
              # Add the expression to the e-graph
              new_eclass_id = egraph.add_instantiation(simplified_node, environment)
              egraph.union(new_eclass_id, old_eclass_id)
              # Save the new e-class ids to assert later
              if args.verify:
                if old_eclass_id not in new_eclass_ids:
                  new_eclass_ids[old_eclass_id] = []
                new_eclass_ids[old_eclass_id].append(new_eclass_id)
              # Update the expected size to be asserted later
              if args.verify:
                if simplified_size < upper_bound_size:
                  upper_bound_size = simplified_size
            # Store the upper bound size for this e-class
            if args.verify:
              upper_bound_sizes[old_eclass_id] = upper_bound_size
            # Rebuild the e-graph at each iteration if we are verifying the correctness
            if args.verify:
              egraph.rebuild()
              extractor.update_costs(node)
          # Rebuild the e-graph
          egraph.rebuild()
          extractor.update_costs(node)
          # Assert the best cost for each of the injected nodes
          if args.verify:
            for old_eclass_id, new_ids in new_eclass_ids.items():
              upper_bound_size = upper_bound_sizes[old_eclass_id]
              for new_eclass_id in new_ids:
                b_size_0, b_node_0 = extractor.find_best(old_eclass_id)
                b_size_1, b_node_1  = extractor.find_best(new_eclass_id)
                b_real_0 = b_node_0.get_node_cost()
                b_real_1 = b_node_1.get_node_cost()
                assert b_size_0 == b_size_1, f"b_size_0: {b_size_0}, b_size_1: {b_size_1}, old_eclass_id: {old_eclass_id}, new_eclass_id: {new_eclass_id}"
                assert b_real_0 == b_real_1, f"b_real_0: {b_real_0}, b_real_1: {b_real_1}, old_eclass_id: {old_eclass_id}, new_eclass_id: {new_eclass_id}"
                assert b_size_0 == b_real_0, f"b_size_0: {b_size_0}, b_real_0: {b_real_0}, b_node_0: {b_node_0.to_exp()}, old_eclass_id: {old_eclass_id}, new_eclass_id: {new_eclass_id}"
                assert b_size_0 <= upper_bound_size, f"b_size_0: {b_size_0}, upper_bound_size: {upper_bound_size}, old_eclass_id: {old_eclass_id}, new_eclass_id: {new_eclass_id}"
      # Harvest the constants and create simple oracle entries
      if args.use_qsynth_inside and args.use_constants_harvest:
        eclass_expressions = extractor.get_eclass_expressions()
        new_harvested_constants = extractor.get_harvested_constants(harvested_constants)
        harvested_constants = harvested_constants.union(new_harvested_constants)
        print(f'Harvested: {len(harvested_constants)} (+{len(new_harvested_constants)})')
        if args.use_constants_harvest_heavy:
          print(f'Subtrees: {len(eclass_expressions)}')
        update_oracle_with_harvested_constants(oracle, harvested_constants, eclass_expressions, mask, args.bits, constants_computation_cache, args.use_constants_harvest_negate, args.use_constants_harvest_heavy)
      # Extract the synthesized node
      synt_cost, synt_node = extractor.find_best(node)
      # Update the original cost
      if not original_cost:
        original_cost = synt_cost
      # Print the information
      print(f'Synthesized (cost = {synt_cost}): {synt_node.to_exp()}')
      end_time = time.time()
      total_time = end_time - start_time
      # Quickly verify if we messed up
      if not bruteforce_verification(synt_node, values, ground_truth, mask):
        print(f'Something went wrong during the synthesis!')
        input()
      # Determine if we need to reset the e-graph
      eclasses_amount = len(egraph.eclasses())
      reset_reason_0 = eclasses_amount > args.e_graph_reset_count
      reset_reason_1 = ((((original_cost - synt_cost) / original_cost) * 100) >= args.e_graph_reset_cost)
      print(f"Reduction: {(((initial_cost - synt_cost) / initial_cost) * 100):.02f}%, Partial: {(((original_cost - synt_cost) / original_cost) * 100):.02f}%, E-Graph: {eclasses_amount}, Reset: {reset_reason_0 or reset_reason_1}, Done: {done}, Elapsed: {total_time:.02f}s")
      # Stop if needed
      if previous_cost == synt_cost:
        same_cost += 1
      else:
        same_cost = 0
      if same_cost > args.e_graph_stop_count:
        break
      # Update the previous cost
      previous_cost = synt_cost
      # Reset if needed
      if reset_reason_0 or reset_reason_1:
        if args.negate_constant_node:
          synt_node = negate_constant_node(synt_node, mask, args.bits)
        if args.explode_multiplication:
          synt_node = explode_multiplication(synt_node)
        if args.strip_opaque_variables:
          synt_node = strip_opaque_variables(synt_node, args.verify, args.bits)
        egraph = EGraph()
        node = egraph.add_expression(synt_node)
        original_cost = synt_cost
      if done:
        break

    end_time = time.time()
    total_time = (end_time - start_time) * 1000

    print(f'Partial time: {total_time:.02f}ms')

    times.append(total_time)

  print(f'Average time: {sum(times)/len(times):.02f}ms')

